window.OSAP_FT=window.OSAP_FT||{};window.OSAP_FT["15"]={"https://www.gov.uk/foreign-travel-advice/brazil":{"r":"govuk","at":"2026-11-17T16:30Z","sha":"729ece0257ba9c602d967744d31302831ab416c597737609e7a5e6079b12a8c4","read":"https://www.gov.uk/api/content/foreign-travel-advice/brazil","bytes":76842,"x":"fulltext v1","title":"Brazil travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-03-18T15:00:20+00:00","mod":"2026-11-17T13:27:42+00:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"p","s":["Your travel insurance could be invalidated if you travel against advice from the Foreign, Commonwealth & Development Office (FCDO)."]},{"k":"h","s":["Areas where FCDO advises against all but essential travel"]},{"k":"hs","s":["Amazonas State"]},{"k":"p","s":["FCDO advises against all but essential travel to the following river areas towards the west of Amazonas State:"]},{"k":"li","s":["along the Amazonas (Amazon) River and its tributaries west of the town of Codajás and east of the town of Belém do Solimões in Amazonas State"]},{"k":"li","s":["along any part of the Itaquaí River in Amazonas State"]},{"k":"li","s":["along any part of the Japurá River or its tributaries in Amazonas State"]},{"k":"li","s":["along the Rio Negro (Black River) and its tributaries north or west of the town of Barcelos in Amazonas State"]},{"k":"p","s":["Find out more about ",["why FCDO advises against travel","https://www.gov.uk/foreign-travel-advice/brazil/regional-risks"],"."]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["FCDO provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/brazil/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of Brazil’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Brazil set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Brazilian Embassy in the UK","https://www.gov.br/mre/pt-br/embaixada-londres"],"."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["To enter Brazil, your passport must have an ‘expiry date’ at least 6 months after the date you arrive."]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"hs","s":["British-Brazilian dual nationals"]},{"k":"p","s":["Brazilian immigration authorities often require dual British-Brazilian nationals visiting Brazil to travel on Brazilian (rather than British) passports."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You can visit Brazil without a visa for up to 90 days for tourism."]},{"k":"p","s":["If you want to extend your tourist visa, contact the ",["Federal Police","https://www.gov.br/pf/pt-br/assuntos/imigracao"]," (in Portuguese) before your visa expires."]},{"k":"p","s":["For more information about visas, contact the ",["Brazilian Consulate in London","https://www.gov.br/mre/pt-br/consulado-londres/consulate-general"],"."]},{"k":"p","s":["If you overstay your visa, you’ll face a daily fine. You have the option to pay this fine either when you leave Brazil or during your next visit."]},{"k":"p","s":["Make sure you get your passport stamped."]},{"k":"p","s":["Make sure the border control officer puts a stamp in your passport. If it is not stamped, you may be fined when you leave."]},{"k":"p","s":["Read about ",["passport stamping if you live in Brazil","https://www.gov.br/pf/pt-br/assuntos/passaporte/ajuda/duvidas_/caderneta/caderneta-carimbo-no-passaporte"]," (in Portuguese)."]},{"k":"h","s":["Travelling with children"]},{"k":"hs","s":["Children with dual British-Brazilian citizenship"]},{"k":"p","s":["British-Brazilian dual nationals under the age of 18 who are travelling without both parents or legal guardians need authorisation from both parents or legal guardians to travel in Brazil or leave the country. Read more about the ",["formal travel authorisation process for Brazilian minors","https://www.gov.br/mre/pt-br/consulado-londres/brazilian-minor-children-travel/travel-consent-for-brazilian-minor-children"]," and the ",["frequently asked questions","https://www.gov.br/mre/pt-br/consulado-londres/brazilian-minor-children-travel/frequently-asked-questions"],"."]},{"k":"hs","s":["Children who are not dual British-Brazilian nationals"]},{"k":"p","s":["Families of non-Brazilian under-18s travelling through Brazil without one or both parents should follow the instructions for dual British-Brazilian under-18s. Make sure the under-18 or their travelling companion also carries the original or notarised copy of the under-18’s birth certificate. Contact the ",["Brazilian Consulate in London","https://www.gov.br/mre/pt-br/consulado-londres/consulate-general"]," for more information."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["For details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Brazil guide","https://travelhealthpro.org.uk/country/34/brazil#Vaccine_Recommendations"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about ",["goods you can take into or out of Brazil","https://www.gov.br/mre/pt-br/consulado-londres/useful-information/visiting-brazil#goods"],". You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"hs","s":["Taking money into Brazil"]},{"k":"p","s":["If you are bringing cash or travellers cheques into Brazil with a value of 10,000 US dollars or more, you will need to ",["declare it online","https://www.gov.br/mre/pt-br/consulado-londres/useful-information/visiting-brazil"],"."]},{"k":"h","s":["Safety and security"]},{"k":"p","s":["This guide also has safety advice for ",["regions of Brazil","https://www.gov.uk/foreign-travel-advice/brazil/regional-risks"],"."]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Brazil"]},{"k":"p","s":["Terrorists are likely to try to carry out attacks in Brazil."]},{"k":"p","s":["Attacks could be indiscriminate including in places visited by foreigners. You should remain aware of your surroundings, keep up to date with local media reports and follow the advice of local authorities. Targets could include:"]},{"k":"li","s":["crowded places"]},{"k":"li","s":["public gatherings"]},{"k":"p","s":["On 13 November 2024, two explosions occurred at the Praça dos Três Poderes in central Brasilia. You should exercise caution around major sites in large Brazilian cities."]},{"k":"h","s":["Protests and civil unrest"]},{"k":"p","s":["Protests, demonstrations and strikes may take place in cities across Brazil. Even peaceful events can become confrontational and may turn violent. Police have used rubber bullets and tear gas to disperse protesters."]},{"k":"p","s":["You should:"]},{"k":"li","s":["avoid political rallies, protests and demonstrations"]},{"k":"li","s":["monitor local media for updates"]},{"k":"li","s":["follow the instructions of local authorities"]},{"k":"p","s":["If you encounter a protest or demonstration, or feel uncomfortable in a large crowd, leave the area as soon as it is safe to do so."]},{"k":"h","s":["Favelas"]},{"k":"p","s":["Favelas (‘slum’ or ‘shanty town’) are urban neighbourhoods of high-density informal housing. They exist in all major Brazilian cities and can border areas used by tourists and visitors."]},{"k":"p","s":["The security situation in many favelas is unpredictable and can be dangerous. Tourists have been shot after accidentally entering favelas."]},{"k":"p","s":["You should:"]},{"k":"li","s":["avoid all favelas, including favela tours marketed to tourists and any accommodation, restaurants or bars advertised as being within a favela"]},{"k":"li","s":["if you’re using GPS navigation, make sure the suggested route does not take you into a favela"]},{"k":"p","s":["If you’re unsure about a location, check with your hotel or the local authorities."]},{"k":"h","s":["Crime"]},{"k":"p","s":["If you’re the victim of crime, contact the local police number 190 or the nearest British embassy or consulate."]},{"k":"p","s":["Read our guidance ",["if you’re the victim of a crime abroad","https://www.gov.uk/guidance/victim-of-crime-abroad"],"."]},{"k":"hs","s":["Theft and robbery"]},{"k":"p","s":["Robberies are common in many cities, particularly on buses. Thieves target mobile phones, particularly between 4pm and 9pm. Attackers may be armed and under the influence of drugs. Do not resist attackers. If threatened, hand over your valuables without resistance."]},{"k":"p","s":["Thefts are particularly common on public beaches and include ‘arrastões’ where large groups of thieves run through an area of the beach grabbing possessions. Keep your belongings close and avoid taking valuables to the beach. Do not go on to city beaches after dark."]},{"k":"p","s":["Pickpocketing is common."]},{"k":"p","s":["Criminals target large-scale celebrations in Brazil, such as the Carnival in major cities. Be aware of your personal security and surroundings. Be cautious about proposals from strangers that take you away from public areas."]},{"k":"p","s":["To reduce your risk:"]},{"k":"li","s":["avoid wearing expensive jewellery and watches"]},{"k":"li","s":["avoid carrying large sums of money"]},{"k":"li","s":["avoid using a mobile phone in the street"]},{"k":"li","s":["leave your passport and valuables in a safe place"]},{"k":"hs","s":["Criminal Kidnapping"]},{"k":"p","s":["Short-term opportunistic kidnapping (called ‘express kidnapping’) can happen. Victims have been kidnapped for a short period of time and driven to an ATM to withdraw money before being abandoned. Express kidnappers may use violence."]},{"k":"hs","s":["Scams"]},{"k":"p","s":["Bank and credit card scams are common in Brazil, including card cloning from ATMs and in shops. Payment machine and beach vendor scams have also been reported, particularly in busy tourist areas, where incorrect amounts may be charged or visitors may be overcharged. Always keep sight of your card and check the amount displayed on the payment terminal before paying. Do not use an ATM if you notice anything suspicious. Ask for a receipt, regularly monitor your bank statements, and contact your bank immediately if you notice any discrepancies."]},{"k":"p","s":["If you withdraw cash at an ATM and the cash has pink marks on it, speak to the bank (or police) straight away to get it changed. It may have been marked as damaged or counterfeit."]},{"k":"p","s":["Dating apps have been used by criminals to target foreign nationals in Brazil, leading to spiking of drinks, robbery and theft from bank accounts. Exercise caution when engaging with such apps, buy and keep hold of your own drinks, share your plans with friends or family, and be vigilant of your belongings including your mobile phone."]},{"k":"hs","s":["Sexual assault and drink spiking"]},{"k":"p","s":["Rape and other sexual offences against tourists are not common, but there have been attacks against both women and men. Some have involved date rape drugs. Buy your own drinks and keep them in sight."]},{"k":"p","s":["If you begin to feel strange, sick or drunk after only a couple of drinks, tell a trusted friend or security staff. They should take you to a safe place, such as your hotel room or a hospital. You can phone the local police, a hospital or the nearest British embassy or consulate for advice."]},{"k":"p","s":["Read our advice on what to do if you have been ",["raped, sexually assaulted or drugged abroad","https://www.gov.uk/guidance/victim-of-rape-and-sexual-assault-abroad"],"."]},{"k":"hs","s":["Methanol poisoning"]},{"k":"p","s":["There have been deaths and cases of serious illness caused by alcoholic drinks containing methanol in Brazil. Take care when buying spirit-based drinks, including gin, vodka and whisky."]},{"k":"p","s":["Even small amounts of methanol can kill. It is not possible to identify methanol in alcoholic drinks by taste or smell. See ",["Travel Aware Drink Spiking and Methanol Poisoning","https://travelaware.campaign.gov.uk/spiking-and-methanol-poisoning/"]," for information about how to reduce the risks."]},{"k":"p","s":["Seek urgent medical attention if you or someone you are travelling with show the ",["signs of methanol poisoning","https://travelaware.campaign.gov.uk/spiking-and-methanol-poisoning/"]," after drinking."]},{"k":"hs","s":["Child sexual abuse"]},{"k":"p","s":["There are cases of sexual abuse of children in Brazil. All sexual activity with children (people under the age of 18) is illegal, regardless of the age of consent locally. If you commit sex offences against children abroad, you can be prosecuted in the UK."]},{"k":"hs","s":["Parental child abduction"]},{"k":"p","s":["Parental child abduction is not common but can happen in Brazil. Dial 190 to report a missing child or go to the nearest police station. Read the ",["guidance on international parental child abduction","https://www.gov.uk/government/publications/international-parental-child-abduction"]," if your child may be at risk of this."]},{"k":"hs","s":["Carjacking"]},{"k":"p","s":["Theft from cars is common. Keep valuables out of sight."]},{"k":"p","s":["Carjacking can happen, particularly on major roads and in tunnels. To reduce your risk:"]},{"k":"li","s":["approach your car with your keys in your hand so you can get into your car quickly"]},{"k":"li","s":["keep doors locked and windows closed"]},{"k":"li","s":["take particular care at traffic lights"]},{"k":"li","s":["be cautious of people approaching to ask for information, especially at night"]},{"k":"li","s":["if driving at night outside the city, avoid stopping at the roadside – if you must stop, try to stop in a well-lit area"]},{"k":"hs","s":["Organised crime and militias"]},{"k":"p","s":["Organised crime groups and militias operate in Brazil, including in many cities. Armed incidents, including police operations, can occur with little warning. Be aware of your surroundings. Avoid favelas and suburbs where possible."]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Personal ID"]},{"k":"p","s":["Always carry a copy of your passport and another form of photo ID if you have one."]},{"k":"hs","s":["Illegal drugs and trafficking scams"]},{"k":"p","s":["Drug trafficking is widespread in Brazil. Bringing drugs in to or out of Brazil in any quantity is illegal and the penalties are severe."]},{"k":"p","s":["You should expect a long jail sentence and heavy fines for possessing, using or smuggling illegal drugs, including when transiting through the airport."]},{"k":"p","s":["British nationals have been targeted through email scams where fraudsters offer a financial reward for travelling to Brazil, where they are then asked to carry items in to or out of Brazil, including to the UK. These items are often illegal drugs. Anyone caught will face detention for drug trafficking, regardless of the circumstances."]},{"k":"p","s":["Airports in Brazil have excellent technology and security for detecting illegal items, including cannabis. This is also used to scan the baggage of transiting passengers."]},{"k":"hs","s":["Electronic smoking devices"]},{"k":"p","s":["All electronic cigarettes and vaping devices are illegal in Brazil, including refills, parts and accessories."]},{"k":"p","s":["Customs officials have the authority to confiscate any vape products found in travellers’ luggage (both checked in and carry on) during inspections."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["There is no legislation against same-sex sexual activity in Brazil. Same-sex marriage is legal and LGBT+ couples have equal rights in law."]},{"k":"p","s":["São Paulo, Rio de Janeiro and other cities hold Pride events, which attract large numbers. These events are usually very peaceful."]},{"k":"p","s":["Brazil is generally tolerant. However, Brazilian society is quite conservative, particularly outside the larger towns and cities. There are reports of discrimination, violence and harassment against the LGBT+ community. Urban areas are usually more accepting."]},{"k":"p","s":["Read more ",["advice for LGBT+ travellers","https://www.gov.uk/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"h","s":["Outdoor activities and adventure tourism"]},{"k":"hs","s":["Swimming safety"]},{"k":"p","s":["Strong currents can be a danger off some beaches. Get local advice before going in the water. Pay attention to warning flags and the location of lifeguards if present on the beach."]},{"k":"p","s":["Shark attacks are a danger, particularly on the beaches around Recife in north-east Brazil. Pay attention to warning signs and consult lifeguards if unsure. Sharks have been known to attack in waist-deep water and deaths have occurred."]},{"k":"p","s":["See ",["water safety on holiday","https://www.rlss.org.uk/safety-on-holiday"]," from the Royal Life Saving Society."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Brazil, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"],"."]},{"k":"p","s":["You can use a UK photocard driving licence to drive in Brazil. If you still have a paper driving licence, you may need to ",["update it to a photocard licence","https://www.gov.uk/exchange-paper-driving-licence"]," or get the ",["1968 version of the international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"]," as well. You cannot buy an IDP outside the UK, so get one before you travel."]},{"k":"p","s":["After 180 days, you need to apply for a Brazilian driving licence."]},{"k":"hs","s":["Driving standards"]},{"k":"p","s":["Brazil has a high road accident rate. Driving standards are poor. Take care on the roads and avoid riding bicycles. In many rural areas, roads are in poor condition away from the main highways. Bus and coach crashes are frequent."]},{"k":"p","s":["Immediately report all accidents to the police: call 190 or go to a police station."]},{"k":"p","s":["Contact the police if vehicles are obstructing traffic and you need help."]},{"k":"hs","s":["Drink-driving"]},{"k":"p","s":["Drink-driving is a serious offence in Brazil and checkpoints are often set up. If you’re caught driving under the influence of alcohol, you will be prosecuted. Penalties range from fines and a suspension from driving for 12 months, to up to 3 years in prison."]},{"k":"hs","s":["Taxi travel"]},{"k":"p","s":["There have been reports of express kidnappings, assaults and robberies from unlicensed taxis, including in cars using fraudulent ride-hailing accounts, such as Uber. Do not hail taxis on the street. There are authorised taxi booths at most airports in Brazil."]},{"k":"p","s":["Ride-hailing apps, such as Uber, are widely available in Brazil. Be wary of unregulated drivers posing as ride-hailing app drivers, especially at airports."]},{"k":"p","s":["Make sure you:"]},{"k":"li","s":["book through the official app"]},{"k":"li","s":["wait in a safe location until your vehicle arrives, including at designated pick-up areas at airports"]},{"k":"li","s":["check the vehicle registration and driver details match"]},{"k":"li","s":["are alert to any diversions or change in destination on the app"]},{"k":"li","s":["do not display your phone or valuables"]},{"k":"li","s":["use available safety features such as trip tracking and location sharing"]},{"k":"hs","s":["Air travel"]},{"k":"p","s":["If you have been a victim of a passport theft and you need to fly to Brasilia, São Paulo or Rio de Janeiro for consular services, you can travel on domestic flights with a valid photo ID or a police report."]},{"k":"p","s":["Check whether your tour operator has concerns about airlines in Brazil."]},{"k":"hs","s":["Sea travel"]},{"k":"p","s":["There have been armed and unarmed attacks on merchant vessels, including British flag vessels off the Brazilian coast and in some Brazilian ports."]},{"k":"hs","s":["Rail travel"]},{"k":"p","s":["There have been instances of theft and robbery on the rail network, including urban metro rail networks. Avoid wearing expensive jewellery and watches or using a mobile phone during train travel."]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["Find out what you can do to ",["prepare for and respond to extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"hs","s":["El Niño 2026-2027"]},{"k":"p","s":["A strong El Niño climate event is expected from late 2026 until early 2027. This may increase the risk of heavy rainfall, flooding and landslides in southern Brazil, and drought, high temperatures and wildfires in northern and north-eastern Brazil. Conditions can change quickly."]},{"k":"p","s":["Sign up for local ",["Civil Defence disaster alerts","https://www.gov.br/pt-br/servicos/solicitar-cadastro-para-recebimento-de-avisos-e-alertas-de-desastres"]," and monitor ",["weather warnings and forecasts","https://portal.inmet.gov.br/"],"."]},{"k":"hs","s":["Heavy rainfall"]},{"k":"p","s":["The rainy season runs from November until March in the south and south-east of Brazil (including Rio de Janeiro) and from April until July in the north-east of Brazil. However heavy rainfall and flooding can also occur outside of the designated rainy seasons, in any region of the country."]},{"k":"p","s":["Heavy rainfall often disrupts infrastructure, particularly in rural areas. Flash floods and landslides are common in regions where mountains are close to the coast, such as Rio de Janeiro. This includes in tourist areas. People have drowned when swept away in fast flowing water. Cars and buses have been caught in landslides, resulting in deaths."]},{"k":"p","s":["Monitor local media and follow local authority warnings which are displayed on digital street signs and sent to hotels and hostels. Follow any instructions given by the local authorities. Avoid travelling on the road during heavy rain. If you are outside when the rain starts, avoid walking in flooded areas, and do not cross fast flowing water, however shallow you think it is."]},{"k":"hs","s":["Forest fires"]},{"k":"p","s":["Forest fires are common from May to September, especially during July and August due to the dry season. They are highly dangerous and unpredictable. Check the latest alerts and ",["weather forecast","https://portal.inmet.gov.br/"]," (in Portuguese) and follow the advice of local authorities if you’re considering travelling to affected areas."]},{"k":"h","s":["Regional risks"]},{"k":"p","s":["This section has safety advice for regions of Brazil. It only covers regions where FCDO has specific advice. You should also read ",["FCDO’s overall travel advice","https://www.gov.uk/foreign-travel-advice/brazil"]," and ",["safety and security advice","https://www.gov.uk/foreign-travel-advice/brazil/safety-and-security"],"."]},{"k":"p","s":["You should monitor local media and follow the guidance of local authorities when travelling in remote areas."]},{"k":"h","s":["Amazonas State"]},{"k":"hs","s":["River travel"]},{"k":"p","s":["FCDO advises against all but essential travel:"]},{"k":"li","s":["along the Amazonas (Amazon) River and its tributaries west of the town of Codajás and east of the town of Belém do Solimões in Amazonas State"]},{"k":"li","s":["along any part of the Itaquaí River in Amazonas State"]},{"k":"li","s":["along any part of the Japurá River or its tributaries in Amazonas State"]},{"k":"li","s":["along the Rio Negro (Black River) and its tributaries north or west of the town of Barcelos in Amazonas State"]},{"k":"p","s":["There are risks to travellers in river areas towards the west of Amazonas State, where Brazil shares borders with Colombia, Peru and Venezuela, due to criminal activity. Armed groups, including pirates and drug traffickers, travel by the river routes in the Amazonas state where is there is low presence of police and local authorities."]},{"k":"h","s":["Rio de Janeiro"]},{"k":"p","s":["The most common incidents affecting British nationals in Rio de Janeiro are thefts and pickpocketing around:"]},{"k":"li","s":["Copacabana beach"]},{"k":"li","s":["Ipanema beach"]},{"k":"li","s":["Lapa"]},{"k":"li","s":["Santa Teresa"]},{"k":"p","s":["Tourists have reported armed robberies on the Corcovado walking trail to the Christ the Redeemer statue. See our advice on ",["Theft and robbery","https://www.gov.uk/foreign-travel-advice/brazil/safety-and-security#theft-and-robbery"],"."]},{"k":"h","s":["São Paulo"]},{"k":"p","s":["The most common incidents affecting British nationals in São Paulo are thefts or pickpocketing around:"]},{"k":"li","s":["Avenida Paulista"]},{"k":"li","s":["the historical downtown area"]},{"k":"li","s":["the red light districts located on Rua Augusta (north of Avenida Paulista)"]},{"k":"li","s":["Catedral da Sé"]},{"k":"li","s":["Praça da República"]},{"k":"li","s":["the Estacao de Luz metro area (where Cracolandia is located)"]},{"k":"li","s":["Pinheiros"]},{"k":"p","s":["See our advice on ",["Theft and robbery","https://www.gov.uk/foreign-travel-advice/brazil/safety-and-security#theft-and-robbery"],"."]},{"k":"h","s":["Brasilia"]},{"k":"hs","s":["Theft"]},{"k":"p","s":["In Brasilia, the central bus station area has a lot of incidents of theft. Theft from pedestrians also happens across the city, especially in the central and southern commercial centres. Take particular care at these locations. See our advice on ",["Theft and robbery","https://www.gov.uk/foreign-travel-advice/brazil/safety-and-security#theft-and-robbery"],"."]},{"k":"h","s":["North-east Brazil"]},{"k":"hs","s":["Theft"]},{"k":"p","s":["The most common incidents affecting British nationals in north-east Brazil are theft from hotel and motel rooms and muggings. Reduce the risk of being mugged by avoiding quiet or deserted areas and by using taxis after sunset instead of walking. See our advice on ",["Theft and robbery","https://www.gov.uk/foreign-travel-advice/brazil/safety-and-security#theft-and-robbery"],"."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Call 192 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccination recommendations for Brazil","https://travelhealthpro.org.uk/country/34/brazil#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Brazil","https://travelhealthpro.org.uk/country/34/brazil"],", including:"]},{"k":"li","s":["yellow fever"]},{"k":"li","s":["dengue"]},{"k":"li","s":["chikungunya"]},{"k":"li","s":["oropouche"]},{"k":"li","s":["high UV levels"]},{"k":"p","s":["Altitude sickness is a risk in parts of Brazil. Read more about ",["altitude sickness on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/26/altitude-illness"],"."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["If you’re taking medication, bring a prescription or letter from your doctor confirming your need to carry the medication. Bring enough to last your whole trip, as some medicines may not be available locally. Counterfeit drugs can be an issue, so it’s better to travel with your own supplies."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Brazil"]},{"k":"p","s":["Foreign nationals are entitled to emergency medical treatment in Brazilian public hospitals. Public hospitals in Brazil, especially in major cities, tend to be overcrowded and there’s often a long wait for a bed and a lack of medication. Private hospitals will not accept you unless you can show evidence of enough money or insurance to cover your treatment."]},{"k":"p","s":["FCDO has a list of ",["medical providers in Brazil","https://www.gov.uk/government/publications/list-of-doctors--2"]," where some staff will speak English."]},{"k":"p","s":["There is also ",["guidance on healthcare if you’re living in Brazil","https://www.gov.uk/guidance/living-in-brazil#healthcare-in-brazil"],"."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Brazil"]},{"k":"p","s":["Ambulance: 192"]},{"k":"p","s":["Fire: 193"]},{"k":"p","s":["Police: 190 or 911"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=brazil"]," and ",["funeral directors","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/funeral-directors?country=brazil"]," in Brazil"]},{"k":"li","s":["dealing with a ",["death in Brazil","https://www.gov.uk/government/publications/brazil-bereavement-packinformation"]]},{"k":"li","s":["being ",["arrested or imprisoned in Brazil","https://www.gov.uk/government/publications/brazil-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of rape or sexual assault in Brazil","https://www.gov.uk/government/publications/rape-and-sexual-assault-in-brazil-local-guide"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/brazil/british-embassy-brasilia"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/brazil/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"h","s":["Risk information for British companies"]},{"k":"p","s":["The Overseas Business Risk service offers ",["information and advice for British companies operating in Brazil","https://www.gov.uk/government/publications/overseas-business-risk-brazil"]," on how to manage political, economic, and business security-related risks."]}],"chars":24831,"change":"New information about the risk of extreme weather due to the El Niño climate event (‘Safety and security’ page)."},"https://www.gov.uk/foreign-travel-advice/canada":{"r":"govuk","at":"2026-11-17T16:30Z","sha":"9d15c591c2c4e3f0c481bd6b82b04cbc32c061dcbcd1adada952f5b3baaa497d","read":"https://www.gov.uk/api/content/foreign-travel-advice/canada","bytes":66581,"x":"fulltext v1","title":"Canada travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-02-18T00:00:00+00:00","mod":"2026-06-02T17:02:41+01:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/canada/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of Canada’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Canada set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Canadian High Commission in the UK","https://www.international.gc.ca/country-pays/united_kingdom-royaume_uni/london-londres.aspx?lang=eng"],"."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["To enter Canada, your passport must be valid for the length of your planned stay."]},{"k":"p","s":["If you’re travelling through another country on your way to or from Canada, check the entry requirements for that country. Many countries will only allow entry if you have at least 6 months validity remaining on your passport."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual Citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["To enter or transit through Canada, most people need a visa or an Electronic Travel Authorization (eTA) – not both."]},{"k":"p","s":[["Check if you need a visa or an eTA online","https://ircc.canada.ca/english/visit/visas.asp"],"."]},{"k":"p","s":["You do not need a visa for short visits (normally up to 6 months). You may need an eTA instead."]},{"k":"p","s":["You do not need an eTA, if you are:"]},{"k":"li","s":["arriving by land and sea – you must have ",["acceptable travel documents and ID","https://www.cbsa-asfc.gc.ca/travel-voyage/td-dv-eng.html"]]},{"k":"li","s":["a British-Canadian dual national – you must have a valid Canadian passport"]},{"k":"p","s":["See ",["Canada’s entry requirements","https://www.canada.ca/en/immigration-refugees-citizenship/services/visit-canada/entry-requirements-country.html"]," for full details of eTA and visa requirements."]},{"k":"p","s":["Contact the ",["Canadian High Commission in the UK","https://www.international.gc.ca/country-pays/united_kingdom-royaume_uni/london-londres.aspx?lang=eng"]," if you are unsure about visa requirements or your eligibility to enter the country, for example, if you have a criminal record or have been arrested."]},{"k":"hs","s":["Checks at border control"]},{"k":"p","s":["Canadian border officials may ask you to show a return or onward ticket and proof that you have sufficient funds to support yourself for the duration of your stay, even if you are staying with family or friends."]},{"k":"hs","s":["Visas for permanent residence, study or work"]},{"k":"p","s":["See information on ",["visas for permanent residence, study or work in Canada","https://www.canada.ca/en/services/immigration-citizenship.html"],"."]},{"k":"h","s":["Ebola"]},{"k":"p","s":["As a public health measure, Canada has introduced temporary border measures for travellers arriving from regions affected by the Ebola outbreak."]},{"k":"p","s":["Canada is suspending certain immigration documents for residents of the Democratic Republic of 4Congo, Uganda and South Sudan until August 28, 2026."]},{"k":"p","s":["Canadian citizens, permanent residents, and foreign nationals entering Canada who, in the previous 21 days, have been in the Democratic Republic of the Congo, Uganda or South Sudan will be given a health assessment upon arrival. Those who do not have symptoms will have to quarantine for 21 days. If they do not have a place where they can quarantine safely, they will be provided with an appropriate location. Travellers who have symptoms will be isolated at a hospital for further assessment. These measures are being implemented under the Quarantine Act. This border measure will be in place until August 29, 2026."]},{"k":"p","s":["The World Health Organisation (WHO) has ",["declared this a Public Health Emergency of International Concern","https://www.who.int/news/item/17-05-2026-epidemic-of-ebola-disease-in-the-democratic-republic-of-the-congo-and-uganda-determined-a-public-health-emergency-of-international-concern"],"."]},{"k":"p","s":["Check the ",["Government of Canada’s official website for more information","https://www.canada.ca/en/public-health/services/diseases/ebola/border-measures.html"],"."]},{"k":"hs","s":["Transiting through Canada"]},{"k":"p","s":["If you are travelling through Canada (transiting) by air, you must have an eTA or a transit visa."]},{"k":"p","s":["If you have questions, contact:"]},{"k":"li","s":["your airline"]},{"k":"li","s":[["Immigration, Refugees and Citizenship Canada","https://www.canada.ca/en/immigration-refugees-citizenship.html"]]},{"k":"li","s":["your nearest Canadian high commission, embassy or consulate"]},{"k":"p","s":[["Find out more about transiting Canada","https://www.canada.ca/en/immigration-refugees-citizenship/services/visit-canada/transit.html"],"."]},{"k":"hs","s":["Visa and eTA scams"]},{"k":"p","s":["Some unauthorised websites charge for submitting visa applications. These websites are not associated with the Canadian government."]},{"k":"p","s":["You can ",["check your eTA status online with the Canadian government","https://onlineservices-servicesenligne.cic.gc.ca/eta/applicationQuery?lang=en"],". If it has been 72 hours since you applied, and you have not received confirmation of your application, ",["complete an enquiry form","https://secure.cic.gc.ca/enquiries-renseignements/canada-case-cas-eng.aspx"],"."]},{"k":"h","s":["Travelling with children"]},{"k":"p","s":["If a child travels alone or with only one parent or legal guardian, they should carry a letter of consent from the non-travelling parents or guardians. Immigration officers have the right to question children using simple and appropriate language to see if there are any concerns about child abduction."]},{"k":"p","s":["For more information, check with the ",["Canadian High Commission in the UK","https://www.international.gc.ca/country-pays/united_kingdom-royaume_uni/london-londres.aspx?lang=eng"]," or the Canada Border Services Agency."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["For details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Canada guide","https://travelhealthpro.org.uk/country/41/canada#Vaccine_Recommendations"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about ",["goods you can take into or out of Canada","https://travel.gc.ca/returning/customs/what-you-can-bring-home-to-canada"],". You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"p","s":["The Canadian authorities will confiscate banned food products and you could get a fine. For more information, see ",["importing food, plants or animals to Canada","https://inspection.canada.ca/importing-food-plants-or-animals/eng/1573836795867/1573836899201"],"."]},{"k":"p","s":["If you visit a farm or have contact with wild animals before entering Canada, and plan to visit a farm during your stay, you must declare this on your Customs Declaration Card. For more information, see ",["biosecurity at the Canadian border","https://inspection.canada.ca/animal-health/terrestrial-animals/biosecurity/general-public/border/eng/1344754371697/1344754930771"],"."]},{"k":"h","s":["Safety and security"]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Canada"]},{"k":"p","s":["Terrorists are likely to try to carry out attacks in Canada."]},{"k":"p","s":["Attacks could be indiscriminate, including in places visited by foreign nationals. You should remain aware of your surroundings, keep up to date with local media reports and follow the advice of local authorities."]},{"k":"p","s":["Recent attacks include:"]},{"k":"li","s":["in 2023, one person stabbed and injured in Surrey, British Columbia"]},{"k":"li","s":["in 2021, 4 people killed and one injured by a vehicle in London, Ontario"]},{"k":"p","s":["See the Canadian government’s national terrorism threat level."]},{"k":"h","s":["Crime"]},{"k":"p","s":["Take precautions to protect yourself from petty crime, including:"]},{"k":"li","s":["not leaving your bag or luggage unattended"]},{"k":"li","s":["keeping luggage out of sight in cars"]},{"k":"li","s":["keeping valuables and passport in a safe location"]},{"k":"li","s":["leaving copies of important documents with family and friends in the UK"]},{"k":"li","s":["carrying a copy of your passport for ID"]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Illegal drugs and cannabis"]},{"k":"p","s":["Illegal drugs carry severe penalties. You should expect a long jail sentence and heavy fines for possessing, using or smuggling illegal drugs, including when transiting through the airport."]},{"k":"p","s":["Recreational cannabis is legally available in Canada. ",["Laws vary depending on the province or territory you are visiting","https://www.canada.ca/en/health-canada/services/drugs-medication/cannabis/laws-regulations/provinces-territories.html"],". It is illegal to take cannabis across the Canadian border without a permit or exemption authorised by Health Canada. Those who attempt to take cannabis out of Canada without the relevant permit face arrest."]},{"k":"p","s":["Airports in Canada have excellent technology and security for detecting illegal items, including cannabis. This is also used to scan the baggage of transiting passengers."]},{"k":"p","s":["See the Canadian Border Services Agency website for more information."]},{"k":"hs","s":["Wildlife"]},{"k":"p","s":["If you are hiking or camping, be considerate and cautious of local wildlife. You should:"]},{"k":"li","s":["take all rubbish with you including food items to avoid attracting animals to your site"]},{"k":"li","s":["be careful around animals with nearby young or nests – they may be aggressive when protecting their territory"]},{"k":"li","s":["research the region to learn about the local wildlife"]},{"k":"li","s":["take particular care if you’re in an area where bears have been sighted"]},{"k":"li","s":["keep a safe distance from any wildlife including marine animals and birds"]},{"k":"li","s":["follow park regulations"]},{"k":"h","s":["Outdoor activities and adventure tourism"]},{"k":"p","s":["See advice on ",["visitor safety","https://parks.canada.ca/voyage-travel/securite-safety"]," when planning outdoor activities and adventure tourism in Canada, and on ",["preparing for winter sports abroad","https://www.gov.uk/guidance/winter-sports-stay-safe-on-the-slopes"],"."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Canada, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"],"."]},{"k":"p","s":["See ",["driving in Canada","https://www.canada.ca/en/immigration-refugees-citizenship/services/new-immigrants/new-life-canada/driving.html"]," for information on traffic and safety laws. Laws vary between provinces and territories, including:"]},{"k":"li","s":["whether you are allowed to turn right on a red light"]},{"k":"li","s":["driving licence requirements – you may need to get an ",["international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"]]},{"k":"p","s":["Take extra care when travelling on country roads and watch out for wild animals. For more information on road conditions and road safety, see ",["Transport Canada","https://tc.canada.ca/en"],", the Canadian Automobile Association and Travel Canada."]},{"k":"p","s":["Hire car companies often have stricter requirements for their customers, such as a year of driving experience, a higher minimum age and holding an IDP."]},{"k":"hs","s":["Driving in winter"]},{"k":"p","s":["In winter, highways are often closed because of snowstorms and avalanches in Alberta, British Columbia and other provinces. Check local weather conditions on The Weather Network."]},{"k":"p","s":["Driving conditions can be dangerous, even when roads remain open during a winter storm. Take care, follow local restrictions or guidelines and make sure your vehicle has snow tyres and emergency supplies. See ",["winter driving advice","https://tc.canada.ca/en/road-transportation/stay-safe-when-driving/winter-driving"],", including vehicle preparation and using winter tyres."]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["Find out what you can do to prepare for and respond to ",["extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"hs","s":["Hurricanes"]},{"k":"p","s":["From July to November, hurricanes can affect coastal areas. Check the US National Hurricane Center, ",["Environment Canada","https://www.canada.ca/en/environment-climate-change.html"]," and The Weather Network websites for the latest weather conditions."]},{"k":"hs","s":["Avalanches"]},{"k":"p","s":["Avalanches can happen in mountainous regions, including Alberta and British Columbia. Always follow avalanche advice and stay away from closed trails. Follow the directions of local guides or instructors. For more information and avalanche news, see the ",["Canadian Avalanche Foundation","https://avalanche.ca/map"]," website."]},{"k":"hs","s":["Earthquakes and tsunamis"]},{"k":"p","s":["Familiarise yourself with safety procedures in the event of an earthquake or tsunami. The Canadian government has ",["information about emergency preparedness","https://www.getprepared.gc.ca/cnt/hzd/index-eng.aspx"],"."]},{"k":"hs","s":["Thunderstorms"]},{"k":"p","s":["Summer thunderstorms are frequent in most parts of Canada, particularly between April and September. They can damage property and threaten lives."]},{"k":"hs","s":["Winter storms"]},{"k":"p","s":["Winter storms, including freezing rain, blizzards and hail, are frequent in many parts of Canada, particularly from November to April. They can make driving conditions dangerous, damage property and threaten lives. Follow local warnings or news for details."]},{"k":"hs","s":["Tornadoes"]},{"k":"p","s":["Tornadoes can happen anywhere in Canada from May to September, but June to July is the peak season in:"]},{"k":"li","s":["southern Ontario"]},{"k":"li","s":["Alberta"]},{"k":"li","s":["south-eastern Quebec"]},{"k":"li","s":["southern Saskatchewan and Manitoba through to Thunder Bay"]},{"k":"li","s":["the interior of British Columbia and western New Brunswick"]},{"k":"p","s":["Follow instructions from Canadian officials or law enforcement. Check the US National Hurricane Center for weather updates."]},{"k":"hs","s":["Wildfires"]},{"k":"p","s":["Wildfires can start at any time, whatever the season, although there is particular risk of fire in the grasslands and forests of western Canada, as well as in forested areas of Quebec, Ontario and Nova Scotia, during the summer months."]},{"k":"p","s":["You should follow local warnings or news for details on the latest outbreaks. The Canadian Wildland Fire Information System shows ",["active wildfires and forecasts","https://cwfis.cfs.nrcan.gc.ca/home"],". You can also monitor wildfire smoke and air quality on ",["the Government of Canada’s website","https://www.canada.ca/en/services/health/healthy-living/environment/air-quality/wildfire-smoke.html"],"."]},{"k":"h","s":["Arctic travel"]},{"k":"p","s":["Parts of Canada are in the Arctic Circle, including some very remote areas of land and sea. Emergency medical assistance and search and rescue are limited in these areas. See ",["Arctic travel safety advice","https://www.gov.uk/guidance/arctic-travel-safety-advice"],"."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel, check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Dial 911 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance or medical assistance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Canada","https://travelhealthpro.org.uk/country/41/canada#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Canada","https://travelhealthpro.org.uk/country/41/canada#General_Information"],", including:"]},{"k":"li","s":["biting insects or ticks"]},{"k":"li","s":["mpox – also see ",["Canada’s Public Health Authority website","https://www.canada.ca/en/public-health/services/diseases/mpox/outbreak-update.html"]," which includes updates on mpox"]},{"k":"p","s":["Altitude sickness is a risk in parts of Canada, including skiing and hiking destinations in the Canadian Rockies such as Banff and Lake Louise. Read more about ",["altitude sickness on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/26/altitude-illness"],"."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["TravelHealthPro explains ",["best practice when travelling with medicines","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Canada"]},{"k":"p","s":["Medical treatment can be very expensive. There are no special arrangements for British visitors."]},{"k":"p","s":["For emergency healthcare, go to a hospital emergency room or a walk-in clinic."]},{"k":"p","s":["If you have dual British-Canadian citizenship, you may still have to pay for medical treatment if you do not meet provincial residency requirements for healthcare. Check with the relevant ",["province or territory health ministry","https://www.canada.ca/en/immigration-refugees-citizenship/services/new-immigrants/new-life-canada/health-care/universal-system.html#ministries"]," for more information."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Canada"]},{"k":"p","s":["Telephone: 911 (ambulance, fire, police)"]},{"k":"hs","s":["Coastguard maritime emergencies"]},{"k":"p","s":["Telephone: 1 800 463 4393"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=Canada"]," and ",["translators and interpreters","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/translators-interpreters?country=Canada"]," in Canada"]},{"k":"li","s":["dealing with a ",["death in Canada","https://www.gov.uk/government/publications/bereavement-information-for-canada"]]},{"k":"li","s":["being ",["arrested in Canada","https://www.gov.uk/government/publications/canada-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you are ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/canada/british-high-commission-ottawa"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/canada/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"h","s":["Risk information for British companies"]},{"k":"p","s":["The Overseas Business Risk service offers ",["information and advice for British companies operating in Canada","https://www.gov.uk/government/publications/overseas-business-risk-canada"]," on how to manage political, economic, and business security-related risks."]}],"chars":15775,"change":"Addition of information about entry requirements for those entering from Ebola-affected regions ('Entry requirements' page)."}};
